{/* MULTI-SURVEY MODAL */}
{showMultiSurveyModal && (
  <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-sm" onClick={() => setShowMultiSurveyModal(false)}>
    <div className="bg-slate-800 border border-slate-600 p-6 rounded-2xl shadow-2xl min-w-[500px]" onClick={e => e.stopPropagation()}>
      <div className="flex items-center justify-between border-b border-slate-700 pb-2 mb-4">
         <h3 className="text-white font-black uppercase text-lg">Multi-Survey Number</h3>
         <button onClick={() => setShowMultiSurveyModal(false)} className="text-slate-400 hover:text-white transition-colors">
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
         </button>
      </div>
      <table className="w-full text-left text-white border-collapse">
         <thead>
            <tr>
              <th className="border-b border-slate-600 py-2 px-2 text-xs uppercase text-slate-400">S.No</th>
              <th className="border-b border-slate-600 py-2 px-2 text-xs uppercase text-slate-400">Survey No</th>
              <th className="border-b border-slate-600 py-2 px-2 text-xs uppercase text-slate-400">Area</th>
              <th className="border-b border-slate-600 py-2 px-2 text-xs uppercase text-slate-400">Layer Color</th>
              <th className="border-b border-slate-600 py-2 px-2 text-xs uppercase text-slate-400 text-center">Action</th>
            </tr>
         </thead>
         <tbody>
            {multiSurveyData.map((row, idx) => (
              <tr key={row.id}>
                <td className="py-2 px-2 border-b border-slate-700 font-bold">{row.sNo}</td>
                <td className="py-2 px-2 border-b border-slate-700">
                  <input type="text" value={row.surveyNo} onChange={e => {
                     const val = e.target.value;
                     setMultiSurveyData(prev => prev.map(r => r.id === row.id ? { ...r, surveyNo: val } : r));
                  }} className="bg-slate-900 border border-slate-600 p-1.5 rounded text-white text-sm w-full outline-none focus:border-fuchsia-500" placeholder="Enter Survey No" />
                </td>
                <td className="py-2 px-2 border-b border-slate-700 text-slate-300 font-mono text-sm">{row.area || '-'}</td>
                <td className="py-2 px-2 border-b border-slate-700">
                   <div className="flex items-center gap-2">
                      <button onClick={() => {
                          setMultiSurveyData(prev => prev.map(r => r.id === row.id ? { ...r, useCustomColor: !r.useCustomColor } : r));
                      }} className={`w-8 h-5 flex items-center rounded-full p-1 transition-colors duration-200 ${row.useCustomColor ? 'bg-emerald-500' : 'bg-slate-600'}`} title="Toggle Color Code">
                          <div className={`bg-white w-3 h-3 rounded-full shadow-md transform transition-transform duration-200 ${row.useCustomColor ? 'translate-x-3' : 'translate-x-0'}`}></div>
                      </button>
                      {row.useCustomColor ? (
                         <input type="color" value={row.color} onChange={(e) => setMultiSurveyData(prev => prev.map(r => r.id === row.id ? { ...r, color: e.target.value } : r))} className="w-6 h-6 p-0 border-0 rounded overflow-hidden cursor-pointer bg-transparent" />
                      ) : (
                         <div className="w-4 h-4 rounded-full border border-slate-500" style={{ backgroundColor: '#38bdf8' }} title="Default Blue"></div>
                      )}
                   </div>
                </td>
                <td className="py-2 px-2 border-b border-slate-700 text-center">
                  {idx === multiSurveyData.length - 1 && (
                    <button onClick={() => {
                       const nextSno = multiSurveyData.length + 1;
                       const colorIdx = nextSno % SURVEY_COLORS.length;
                       setMultiSurveyData(prev => [...prev, { id: Date.now().toString(), sNo: nextSno, surveyNo: '', area: '', color: SURVEY_COLORS[colorIdx], useCustomColor: false }]);
                    }} className="text-emerald-400 hover:text-emerald-300 p-1" title="Add Row">
                      <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                    </button>
                  )}
                </td>
              </tr>
            ))}
            {multiSurveyData.length === 0 && (
              <tr>
                <td colSpan="5" className="py-4 px-2 text-center text-slate-500 text-sm italic">
                   No surveys added yet. Draw a line to start or add one manually.
                   <div className="mt-2">
                      <button onClick={() => {
                         setMultiSurveyData([{ id: Date.now().toString(), sNo: 1, surveyNo: '', area: '', color: SURVEY_COLORS[1], useCustomColor: false }]);
                      }} className="text-fuchsia-400 hover:text-fuchsia-300 underline font-bold">Add Survey</button>
                   </div>
                </td>
              </tr>
            )}
         </tbody>
      </table>
      <div className="mt-4 text-xs text-slate-400">
         <span className="font-bold text-sky-400">Tip:</span> Enable the toggle to assign a unique color layer to a survey. If disabled, lines will use the default blue.
      </div>
    </div>
  </div>
)}

